import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.reduce.js";
/* eslint-disable */
import { initiate_customer_transaction } from "@/graphql/mutations.js";
import { format_Date, formatdisplayDate } from "@/JsonFiles/DateFormate.js";
import { reverse_customer_transaction } from "@/graphql/mutations.js";
import { list_transactions_of_invoice } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
import { Auth } from "aws-amplify";
export default {
  components: {
    SnackBar
  },
  props: {
    itemValue: Object,
    TransactionDetails: Object,
    customerData: Array
  },
  data() {
    return {
      minDate: new Date().toISOString().substr(0, 10),
      date: new Date().toISOString().substr(0, 10),
      datePicker: false,
      tempDate: null,
      computedDateFormatted: this.formatDate(new Date()),
      menu: false,
      reversetransactioncard: false,
      amountSetteled: false,
      recentrevesed: true,
      reason_reverse: "",
      invoiceTransaction: [],
      amount: "",
      invoiceNo: "",
      comments: "",
      imageUrl: "",
      imageCheck: true,
      settleInvoice: false,
      s3ImageUrl: "",
      selectedFile: null,
      Give_Got_Type: "You_Gave",
      loading: false,
      contentHeight: 0,
      SnackBarComponent: {},
      rules: {
        required: value => !!value || "This field is required",
        positiveNumber: value => value && parseFloat(value) > 0 || "Amount must be greater than 0"
      }
    };
  },
  mounted() {
    this.contentHeight = window.innerHeight - 200;
    this.listingTransation();
  },
  computed: {
    computedDateDisplay() {
      return this.displayFormatDate(this.computedDateFormatted);
    }
  },
  methods: {
    settlePayment() {
      this.settleInvoice = true;
      this.amount = this.TransactionDetails.pending_amount;
      this.invoiceNo = this.TransactionDetails.invoice_number;
    },
    isPdf(dataUrl) {
      return dataUrl.startsWith("data:application/pdf");
    },
    pdfDataUrl(base64) {
      // For safety: if already a full data URL, return as-is
      if (base64.startsWith("data:application/pdf")) return base64;
      return `data:application/pdf;base64,${base64}`;
    },
    uploadImage(event) {
      const file = event.target.files[0];
      if (file && (file.type.startsWith("image/") || file.type === "application/pdf")) {
        this.selectedFile = file;
        const reader = new FileReader();
        reader.onload = e => {
          this.imageUrl = e.target.result;
        };
        reader.readAsDataURL(file);
      } else {
        // alert("Please upload a valid image file.");
      }
    },
    removeImage() {
      this.imageUrl = "";
      this.selectedFile = null;
    },
    async upload_new_func() {
      if (!this.selectedFile) return;
      await Auth.currentCredentials();
      const orgDetails1 = this.$store.getters.GetOrgDetails;
      const s3_details = {
        bucket_name: "stichh-medias",
        region: "us-east-1"
      };
      // const userId = this.$store.getters.GetUserObj.user.user_id;

      const key = `workflow/${orgDetails1.organization.organization_id}-${this.itemValue.customer.customer_id}/${Date.now()}-${this.selectedFile.name.split(" ").join("")}`;
      try {
        const fileUrl = await uploadToS3(this.selectedFile, s3_details, key);
        if (fileUrl) {
          // console.log("✅ Uploaded file URL:", fileUrl);
          return fileUrl;
        }
      } catch (err) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Upload failed. ",
          timeout: 5000,
          Top: true
        };
        this.loading = false;
      }
    },
    triggerFileInput() {
      this.$refs.fileInput.click();
    },
    isImage(url) {
      return /\.(jpeg|jpg|gif|png|webp|bmp|svg)$/i.test(url);
    },
    close_dialog() {
      if (this.reversetransactioncard) {
        this.reversetransactioncard = false;
      } else if (this.settleInvoice) {
        this.settleInvoice = false;
      } else {
        this.$emit("clicked", 0);
      }
    },
    formatTimestamp(unixTimestamp) {
      if (!unixTimestamp) return "";
      const date = new Date(unixTimestamp * 1000);
      return date.toLocaleString("en-US", {
        hour: "numeric",
        minute: "numeric",
        hour12: true
      });
    },
    get_updatedate(date) {
      if (date != "" && date != undefined) {
        return format_Date(date);
      }
    },
    updatedate(date) {
      if (date != "" && date != undefined) {
        return formatdisplayDate(date);
      }
    },
    reverse_transaction() {
      this.reversetransactioncard = true;
    },
    async validate_form() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.confirm_ReverseTransaction();
      }
    },
    async processAndSave() {
      const validation = await this.$refs.form1.validate(); // Validate form before saving

      if (!validation.valid) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Please fill all required fields correctly.",
          timeout: 5000,
          Top: true
        };
        return;
      }
      if (Number(this.amount) > Number(this.TransactionDetails.pending_amount)) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "The amount exceeds the billing amount",
          timeout: 5000,
          Top: true
        };
        return;
      }
      this.loading = true;
      try {
        this.s3ImageUrl = this.selectedFile ? await this.upload_new_func() : "";
        // console.log(this.s3ImageUrl)
        await this.saveData();
      } catch (error) {
        console.error("Error in processAndSave:", error);
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Error uploading image or saving data.",
          timeout: 5000,
          Top: true
        };
      } finally {
        this.loading = false;
      }
    },
    async listingTransation() {
      try {
        let result = await API.graphql(graphqlOperation(list_transactions_of_invoice, {
          input: {
            invoice_id: this.TransactionDetails.invoice_id
          }
        }));
        let response = JSON.parse(result.data.list_transactions_of_invoice);
        if (response.Status === "SUCCESS") {
          this.invoiceTransaction = response.data;
          this.reversetransactioncard = false;
          this.settleInvoice = false;
          const mostRecentTransaction = this.invoiceTransaction.reduce((latest, current) => {
            return current.transaction_timestamp > latest.transaction_timestamp ? current : latest;
          });
          // console.log(mostRecentTransaction);
          if (mostRecentTransaction.amount_paid == this.TransactionDetails.amount_paid) {
            this.recentrevesed = true;
          } else {
            this.recentrevesed = false;
          }
          if (this.invoiceTransaction[0].pending_amount == 0) {
            this.amountSetteled = true;
          }
        } else {
          this.recentrevesed = true;
          this.invoiceTransaction = [];
        }
      } catch (error) {
        this.recentrevesed = true;
        this.invoiceTransaction = [];
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0]?.message || "Error saving data.",
          timeout: 5000,
          Top: true
        };
      }
    },
    async saveData(fileUrl) {
      try {
        let result = await API.graphql(graphqlOperation(initiate_customer_transaction, {
          input: {
            customer_id: this.itemValue.customer.customer_id,
            invoice_number: this.invoiceNo,
            amount: this.amount,
            comments: this.comments,
            transaction_date: this.date,
            attachments: this.s3ImageUrl,
            bill_settling_type: this.Give_Got_Type === "You_Gave" ? "PAID" : "RECEIVED"
          }
        }));
        let response = JSON.parse(result.data.initiate_customer_transaction);
        if (response.Status === "SUCCESS") {
          this.loading = false;
          this.reversetransactioncard = false;
          this.settleInvoice = false;
          this.listingTransation();
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0]?.message || "Error saving data.",
          timeout: 5000,
          Top: true
        };
      }
    },
    async confirm_ReverseTransaction() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(reverse_customer_transaction, {
          input: {
            transaction_id: this.TransactionDetails.transaction_id,
            comments: this.reason_reverse,
            attachments: this.TransactionDetails.attachments.length === 1 && this.TransactionDetails.attachments[0] === "" ? "" : this.TransactionDetails.attachments,
            transaction_date: this.TransactionDetails.transaction_date,
            user_email_id: this.TransactionDetails.user_email_id
          }
        }));
        this.loading = false;
        let response = JSON.parse(result.data.reverse_customer_transaction);
        if (response.Status == "SUCCESS") {
          this.loading = false;
          this.reversetransactioncard = false;
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        } else {
          this.loading = false;
          this.reversetransactioncard = false;
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.customerLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    displayFormatDate(date) {
      if (!date) return "";
      const [year, month, day] = date.split("-");
      return `${day}/${month}/${year}`;
    },
    formatDate(date) {
      const d = new Date(date);
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, "0");
      const day = String(d.getDate()).padStart(2, "0");
      return `${year}-${month}-${day}`;
    },
    saveDate() {
      this.date = this.tempDate;
      this.computedDateFormatted = this.tempDate ? this.formatDate(this.tempDate) : "";
      this.datePicker = false;
    }
  }
};
